use std::{fs,path::Path,collections::{BTreeMap,BTreeSet}};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-arithmetic-leaves";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn add(p:impl AsRef<Path>,pins:&mut BTreeMap<String,String>){let p=p.as_ref();pins.insert(p.display().to_string(),hash(p));}
fn prior()->BTreeSet<String>{let mut ids:BTreeSet<String>=serde_json::from_value(read("/tmp/zopro-g2-tree-sdk/context/manifest.json")["prior_proof_sha256"].clone()).unwrap();assert_eq!(ids.len(),5958);for path in ["/tmp/zopro-g2-tree-sdk/proof-inventory.json","/tmp/zopro-g1-quarter-current/proof-inventory.json","/tmp/zopro-pairing-x-chain-sdk/proof-inventory.json","/tmp/zopro-control-rescheduling/all-proof-inventory.json","/tmp/zopro-pairing-clean/proof-inventory.json","/tmp/zopro-borrowed-pending/proof-inventory.json","/tmp/zopro-borrowed-g1/proof-inventory.json","/tmp/zopro-poseidon-frontier/proof-inventory.json","/tmp/zopro-poseidon-fused-dot/proof-inventory.json","/tmp/zopro-poseidon-direct-dot/proof-inventory.json","/tmp/zopro-sdk-paired-control/proof-inventory.json"]{for(p,h)in read(path).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());if p.ends_with(".proof"){assert!(ids.insert(h.as_str().unwrap().into()));}}}assert_eq!(ids.len(),7177);ids}
fn setup(){let r=Path::new(R);assert_eq!(read(r.join("native/result.json"))["status"],"complete");assert_eq!(read(r.join("native/core/tests.json"))["passed_tests"].as_array().unwrap().len(),111);let a=read(r.join("native/trace/artifacts.json"));let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("source-pins.json"))).unwrap();for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());add(p,&mut pins);}assert_eq!(hash(a["binary"].as_str().unwrap()),a["binary_sha256"].as_str().unwrap());add(a["binary"].as_str().unwrap(),&mut pins);
 for rel in ["prepare.rs","prepare","analyze.rs","analyze","close.rs","close","native/trace/artifacts.json","native/result.json","native-plan.json","source-audit.json","pre-capture-correction.md","serial-scopes.md","insertion-counts.json"]{add(r.join(rel),&mut pins);}for p in ["/tmp/zopro-gnark-verify/verify","/tmp/zopro-xtask-fast-screen-target/release/xtask","/tmp/zopro-grouping-module/native/candidate-sdk","/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"]{add(p,&mut pins);}let config=read("/tmp/zopro-pairing-x-chain-sdk/perf-plan.json");let cases:Vec<_>=config["cases"].as_array().unwrap().iter().filter(|c|c["workers"]==32).cloned().collect();for c in &cases{for name in ["image","request"]{add(c[name].as_str().unwrap(),&mut pins);}}let ids=prior();save(r.join("prior-proofs.json"),&json!(ids));add(r.join("prior-proofs.json"),&mut pins);
 let mut jobs=Vec::new();let mut steps=Vec::new();for c in &cases{for mode in if c["shape"]=="1x2"{vec!["off","on"]}else{vec!["off"]}{let name=format!("{}-{mode}",c["shape"].as_str().unwrap());let stem=Path::new(c["image"].as_str().unwrap()).file_stem().unwrap();let output=r.join("preflight-proofs").join(&name).join(stem);let mut env=config["environment"].clone();env["RAYON_NUM_THREADS"]=json!("4");steps.push(json!({"kind":"command","name":name,"argv":["taskset","-c","0-3",a["binary"],c["image"],c["request"],"1",output,mode],"environment":env,"timeout_seconds":600}));steps.push(json!({"kind":"command","name":format!("verify-{name}"),"argv":["/tmp/zopro-gnark-verify/verify","/tmp/zopro-keys",output.parent().unwrap(),"/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"],"timeout_seconds":120}));jobs.push(json!({"name":name,"shape":c["shape"],"mode":mode,"workers":4,"rounds":1,"output":output,"public_sha256":c["public_sha256"]}));}}assert_eq!(jobs.len(),10);save(r.join("preflight-jobs.json"),&json!(jobs));save(r.join("capture-base-pins.json"),&json!(pins));save(r.join("preflight-plan.json"),&json!({"version":1,"source_pins":r.join("capture-base-pins.json"),"steps":steps}));println!("Frozen all9OFF+primaryONpreflight40SDK10exports; prior7177");}
fn qualify(){let r=Path::new(R);assert_eq!(read(r.join("preflight/result.json"))["status"],"complete");let mut ids=prior();let mut inventory=BTreeMap::new();for job in read(r.join("preflight-jobs.json")).as_array().unwrap(){let output=Path::new(job["output"].as_str().unwrap());let p=output.join("0.proof");let public=output.join("0.public");assert_eq!(fs::metadata(&p).unwrap().len(),164);assert_eq!(hash(&public),job["public_sha256"].as_str().unwrap());assert!(ids.insert(hash(&p)));for p in [p,public]{inventory.insert(p.display().to_string(),hash(p));}let verify=fs::read_to_string(r.join(format!("preflight/verify-{}/stdout.log",job["name"].as_str().unwrap()))).unwrap();assert!(verify.contains("verified 1 distinct proofs across 1 pinned keys"));}assert_eq!(ids.len(),7187);save(r.join("preflight-proof-inventory.json"),&json!(inventory));let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("capture-base-pins.json"))).unwrap();for rel in ["preflight-plan.json","preflight/result.json","preflight-proof-inventory.json"]{add(r.join(rel),&mut pins);}let config=read("/tmp/zopro-pairing-x-chain-sdk/perf-plan.json");let c=config["cases"].as_array().unwrap().iter().find(|c|c["name"]=="1x2-w32").unwrap();let a=read(r.join("native/trace/artifacts.json"));let mut jobs=Vec::new();let mut steps=Vec::new();for block in 0..3{let workers=if block%2==0{[16,32]}else{[32,16]};for(index,workers)in workers.into_iter().enumerate(){let mut modes=vec!["accepted","off","on"];modes.rotate_left((block+index)%3);if block%2==1{modes.reverse();}for mode in modes{let name=format!("b{block}-w{workers}-{mode}");let output=r.join("proofs").join(&name).join("transfer_confidential_1_2");let mut env=config["environment"].clone();env["RAYON_NUM_THREADS"]=json!(workers.to_string());let binary=if mode=="accepted"{json!("/tmp/zopro-grouping-module/native/candidate-sdk")}else{a["binary"].clone()};let mut argv=vec![json!("taskset"),json!("-c"),json!(format!("0-{}",workers-1)),binary,c["image"].clone(),c["request"].clone(),json!("31"),json!(output)];if mode!="accepted"{argv.push(json!(mode));}steps.push(json!({"kind":"command","name":name,"argv":argv,"environment":env,"timeout_seconds":600}));steps.push(json!({"kind":"command","name":format!("verify-{name}"),"argv":["/tmp/zopro-gnark-verify/verify","/tmp/zopro-keys",output.parent().unwrap(),"/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"],"timeout_seconds":120}));jobs.push(json!({"name":name,"block":block,"workers":workers,"mode":mode,"rounds":31,"output":output,"public_sha256":c["public_sha256"]}));}}}assert_eq!(jobs.len(),18);save(r.join("jobs.json"),&json!(jobs));add(r.join("jobs.json"),&mut pins);save(r.join("capture-pins.json"),&json!(pins));save(r.join("capture-plan.json"),&json!({"version":1,"source_pins":r.join("capture-pins.json"),"steps":steps}));println!("Allpreflightexportsverified;matrix18processes612SDK18exports;next7205onlyifcomplete");}
fn main(){match std::env::args().nth(1).as_deref(){Some("setup")=>setup(),Some("qualify")=>qualify(),_=>panic!("mode")}}
